// Generated by Cypress Author on 2026-11-18

describe('Home Page Landing View', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('visit / → renders hero section with portrait image and overlay', () => {
    cy.get('section[aria-label="Delisha Marie Portrait"]').should('be.visible');

    cy.get('img[alt="Delisha Marie sitting in an armchair with her coffee"]')
      .should('be.visible')
      .and('have.attr', 'src')
      .should('include', 'delisha-marie.jpg');

    cy.get('.image-overlay').should('exist');
  });

  it('visit / → displays site header with logo branding and navigation links', () => {
    cy.get('dm-header').should('be.visible');
    cy.get('dml-header-logo').should('be.visible');
    cy.get('dml-header-logo').contains('Delisha').should('be.visible');
    cy.get('dml-header-logo').contains('Marie').should('be.visible');

    cy.get('dml-header-nav').should('be.visible');
    cy.get('dml-header-nav').contains('a', 'About').should('be.visible');
    cy.get('dml-header-nav').contains('a', 'Contact').should('be.visible');
    cy.get('dml-header-nav').contains('a', 'Kitchen').should('be.visible');
  });

  it('visit / → displays footer with links, copyright text, and back-to-top action', () => {
    const currentYear = new Date().getFullYear();

    cy.get('dm-footer').should('be.visible');
    cy.get('dm-footer').contains('a', 'Back to the top').should('be.visible');
    cy.get('dm-footer').contains('a', 'About').should('be.visible');
    cy.get('dm-footer').contains('a', 'Contact').should('be.visible');
    cy.get('dm-footer').contains('a', 'Kitchen').should('be.visible');
    cy.get('dm-footer')
      .contains(`© ${currentYear} Delisha Marie. Designed by The One.`)
      .should('be.visible');

    // Click back to top action
    cy.get('dm-footer').contains('a', 'Back to the top').click();
    cy.window().its('scrollY').should('equal', 0);
  });

  it('view on mobile viewport → maintains responsive hero layout', () => {
    cy.viewport('iphone-x');
    cy.get('section[aria-label="Delisha Marie Portrait"]').should('be.visible');
    cy.get('.image-wrapper').should('be.visible');
    cy.get('img[alt="Delisha Marie sitting in an armchair with her coffee"]').should('be.visible');
  });
});
